const staticData = $getWorkflowStaticData('global');
staticData.failedSourceIds = [];
staticData.succeededSourceIds = [];
staticData.normalizedItems = [];

let rows = [];
const inputs = $input.all();
if (inputs.length === 1 && Array.isArray(inputs[0].json)) {
  rows = inputs[0].json;
} else {
  rows = inputs.map(i => i.json);
}

const seen = new Set();
const uniqueSources = [];
for (const row of rows) {
  const s = row.sources;
  if (!s || s.status !== 'active') continue;
  if (seen.has(s.id)) continue;
  seen.add(s.id);
  uniqueSources.push({ json: { source_id: s.id, type: s.type, name: s.name, url_or_handle: s.url_or_handle } });
}
return uniqueSources;

const staticData = $getWorkflowStaticData('global');

function decodeEntities(s) {
  return s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'");
}
function extractTag(block, tag) {
  const re = new RegExp('<' + tag + '\\b[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i');
  const m = block.match(re);
  if (!m) return null;
  let val = m[1].trim();
  const cdata = val.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
  if (cdata) val = cdata[1].trim();
  return decodeEntities(val);
}
function extractLink(block) {
  let m = block.match(/<link\b[^>]*\bhref=["']([^"']+)["'][^>]*\/?>/i);
  if (m) return m[1];
  m = block.match(/<link\b[^>]*>([\s\S]*?)<\/link>/i);
  if (m) return m[1].trim();
  return null;
}
function parseFeed(xml) {
  const entries = [];
  const blockRegex = /<(item|entry)\b[^>]*>([\s\S]*?)<\/\1>/gi;
  let m;
  while ((m = blockRegex.exec(xml)) !== null) {
    const block = m[2];
    const title = extractTag(block, 'title');
    const link = extractLink(block);
    const date = extractTag(block, 'pubDate') || extractTag(block, 'published') || extractTag(block, 'updated');
    if (title && link) entries.push({ title, link, date });
  }
  return entries;
}
const resolveYoutubeFeedUrl = async (urlOrHandle) => {
  let handle = urlOrHandle.trim();
  if (/^UC[\w-]{22}$/.test(handle)) {
    return 'https://www.youtube.com/feeds/videos.xml?channel_id=' + handle;
  }
  let m = handle.match(/\/channel\/(UC[\w-]{22})/);
  if (m) return 'https://www.youtube.com/feeds/videos.xml?channel_id=' + m[1];
  let handlePart = handle;
  let hm = handle.match(/youtube\.com\/(@[\w.-]+)/i);
  if (hm) handlePart = hm[1];
  if (!handlePart.startsWith('@')) handlePart = '@' + handlePart;
  const pageUrl = 'https://www.youtube.com/' + handlePart;
  const raw = await this.helpers.httpRequest({ url: pageUrl });
  const html = Buffer.isBuffer(raw) ? raw.toString('utf-8') : String(raw);
  // NOT: /"channelId":"UC..."/ ile ILK eslesmeyi almak YANLIS -- kanal sayfasindaki ilk
  // channelId cogunlukla onerilen/ilgili bir baska kanaldir (@pbsspacetime -> PBS Documentaries,
  // @minutephysics -> MinuteEarth, @veritasium -> Veritasium en Francais). Kanalin KENDI id'si
  // externalId / canonical link / rssUrl alanlarinda bulunur; ucu de tutarlidir.
  const cm = html.match(/"externalId":"(UC[\w-]{22})"/)
    || html.match(/<link rel="canonical" href="https:\/\/www\.youtube\.com\/channel\/(UC[\w-]{22})">/)
    || html.match(/"rssUrl":"[^"]*channel_id=(UC[\w-]{22})"/);
  if (!cm) throw new Error('Could not resolve channel id for handle ' + handlePart);
  return 'https://www.youtube.com/feeds/videos.xml?channel_id=' + cm[1];
};

const results = [];
for (const item of $input.all()) {
  const src = item.json;
  try {
    let feedUrl;
    if (src.type === 'youtube') {
      feedUrl = await resolveYoutubeFeedUrl(src.url_or_handle);
    } else {
      feedUrl = src.url_or_handle;
    }
    const raw = await this.helpers.httpRequest({ url: feedUrl });
    const xmlStr = Buffer.isBuffer(raw) ? raw.toString('utf-8') : String(raw);
    const entries = parseFeed(xmlStr);
    for (const e of entries) {
      const d = e.date ? new Date(e.date) : null;
      const publishedAt = (d && !isNaN(d.getTime())) ? d.toISOString() : new Date().toISOString();
      staticData.normalizedItems.push({
        source_id: src.source_id,
        title: e.title,
        url: e.link,
        published_at: publishedAt,
        content_type: src.type,
        summary: null
      });
    }
    staticData.succeededSourceIds.push(src.source_id);
  } catch (err) {
    staticData.failedSourceIds.push(src.source_id);
  }
  results.push(item);
}
return results;

const staticData = $getWorkflowStaticData('global');
const payload = {
  items: staticData.normalizedItems || [],
  failed_source_ids: staticData.failedSourceIds || [],
  succeeded_source_ids: staticData.succeededSourceIds || []
};
staticData.normalizedItems = [];
staticData.failedSourceIds = [];
staticData.succeededSourceIds = [];
return [{ json: payload }];
